using System.Collections;
using System.Globalization;
using System.Text.Json;
using System.Text.Json.Nodes;
using SPTarkov.Server.Core.Models.Eft.Common.Tables;
using SPTarkov.Server.Core.Utils.Json.Converters;
using C=EscapeFromBorderlands.Client;
using S=EscapeFromBorderlands.Server;
using L=EscapeFromBorderlands.Legacy;
using Item=EFT.InventoryLogic.Item;

int cases=0,assertions=0,failures=0;
void Check(bool ok,string message){assertions++;if(!ok)throw new Exception(message);}
void Near(double a,double b,string message)=>Check(Math.Abs(a-b)<1e-8,$"{message}: {a} != {b}");
void Run(string name,Action test){cases++;try{test();Console.WriteLine("PASS "+name);}catch(Exception e){failures++;Console.WriteLine("FAIL "+name+": "+e);}}
var client=C.LegendaryCatalog.Load();var server=S.LegendaryCatalog.Load();
var originals=client.Variants.Where(v=>v.BackpackEffect!=null&&v.StorageRollVersion==0).ToArray();
var layouts=client.Variants.Where(v=>v.BackpackEffect!=null&&v.StorageRollVersion==C.BackpackStorageVariants.CurrentLayoutVersion&&!v.IsMysteryFleaOffer).ToArray();
var byServer=server.Variants.ToDictionary(v=>v.TemplateId,StringComparer.Ordinal);
var opts=new JsonSerializerOptions{Converters={new StringToMongoIdConverter()}};
TemplateItemProperties Base(){var properties=JsonSerializer.Deserialize<TemplateItemProperties>("""
{"Width":2,"Height":3,"BackgroundColor":"orange","GridLayoutName":"test-layout","Grids":[{"_id":"111111111111111111111111","_name":"main","_parent":"222222222222222222222222","_props":{"cellsH":6,"cellsV":7,"filters":[]}},{"_id":"333333333333333333333333","_name":"pocket","_parent":"222222222222222222222222","_props":{"cellsH":2,"cellsV":2,"filters":[]}}]}
""",opts)!;
// Native required string setters intern their inputs. Supply non-null defaults
// for the minimal synthetic template, as the real database does.
foreach(var p in typeof(TemplateItemProperties).GetProperties().Where(p=>p.PropertyType==typeof(string)&&p.CanRead&&p.CanWrite&&p.GetIndexParameters().Length==0))if(p.GetValue(properties)==null)p.SetValue(properties,string.Empty);
return properties;}
JsonObject Node(TemplateItemProperties p)=>JsonSerializer.SerializeToNode(p,opts)!.AsObject();
C.RarityResolver.ShotRoll Roll(string template,string id)=>C.RarityResolver.Resolve(new Item{Id=id,StringTemplateId=template})!;
string Fingerprint(C.RarityResolver.ShotRoll r)=>string.Join("|",r.AffixDescriptions)+$"/{r.Backpack.Movement}/{r.Backpack.Ergonomics}/{r.Backpack.StaminaCapacity}/{r.Backpack.FrameWeight}/{r.Backpack.ContentsWeight}/{r.Backpack.OverweightThreshold}/{r.Backpack.SearchTime}/{r.Backpack.SprintCost}/{r.Backpack.LegRecovery}/{r.Backpack.AimCost}/{r.Backpack.MovementNoise}";
string BoonIdentity(string line) => new[]{"Light Frame","Balanced Cargo","Load Harness"}.FirstOrDefault(line.StartsWith) ??
 (line.StartsWith("Expanded Storage")||line.StartsWith("Widened Storage")?line.Replace("main compartment","largest compartment"):line);
void Compatible(IReadOnlyList<string> current,IReadOnlyList<string> historical){Check(current.Count==historical.Count,"same four selected boons");Check(current.Select(BoonIdentity).SequenceEqual(historical.Select(BoonIdentity)),"same selections and unchanged unrelated boon values");}
void UpdatedBoons(C.RarityResolver.ShotRoll r){Near(r.Backpack.FrameWeight,1,"old frame discount removed");Near(r.Backpack.ContentsWeight,1,"old cargo discount removed");Near(r.Backpack.OverweightThreshold,1,"old overweight threshold removed");Near(r.Backpack.Movement,r.AffixDescriptions.Any(l=>l.StartsWith("Light Frame"))?1.1f:1f,"fixed movement boon");var cargo=r.AffixDescriptions.Any(l=>l.StartsWith("Balanced Cargo"));Check(cargo?r.Backpack.Ergonomics is >1.099f and <1.151f:r.Backpack.Ergonomics==1,"ergonomics within10-15%");var load=r.AffixDescriptions.Any(l=>l.StartsWith("Load Harness"));Check(load?r.Backpack.StaminaCapacity is >1.099f and <1.201f:r.Backpack.StaminaCapacity==1,"stamina capacity within10-20%");}
Run("Every Legendary backpack has nine current layouts plus legacy compatibility",()=>{Check(originals.Length==67,"67 original signatures");Check(layouts.Length==67*9,"nine combinations each");Check(client.Variants.Select(v=>v.TemplateId).Distinct().Count()==client.Variants.Count,"no ID collision");Check(!client.Variants.Select(v=>v.TemplateId).Intersect(server.LegacyAliases.Select(v=>v.TemplateId)).Any(),"no alias collision");foreach(var b in originals){Check(!b.SpawnEnabled,"old ID compatibility only");Check(layouts.Count(v=>v.StorageFamilyId==b.TemplateId)==9,"one complete family");}});
Run("Both sides derive identical template IDs, dimensions, effects and weights",()=>{Check(client.Variants.Count==server.Variants.Count,"catalog size agreement");foreach(var c in client.Variants){var s=byServer[c.TemplateId];Check(c.SourceTemplateId==s.SourceTemplateId&&c.StorageRows==s.StorageRows&&c.StorageColumns==s.StorageColumns&&c.SpawnEnabled==s.SpawnEnabled&&c.SpawnWeight==s.SpawnWeight,"definition agreement");if(c.BackpackEffect!=null)Check(c.BackpackEffect.ExtraRows==s.BackpackEffect!.ExtraRows&&c.BackpackEffect.ExtraColumns==s.BackpackEffect.ExtraColumns,"grid agreement");}});
Run("Repeated catalog expansion and loading never duplicate or grow layouts",()=>{var n=client.Variants.Count;C.BackpackStorageVariants.Expand(client.Variants);S.BackpackStorageVariants.Expand(server.Variants);Check(n==client.Variants.Count&&n==server.Variants.Count,"idempotent expansion");Check(C.LegendaryCatalog.Load().Variants.Select(v=>v.TemplateId).SequenceEqual(client.Variants.Select(v=>v.TemplateId)),"restart IDs stable");});
Run("Four random bonuses include each requested row/column amount",()=>{foreach(var v in layouts)for(var i=0;i<12;i++){var r=Roll(v.TemplateId,$"layout-{v.TemplateId}-{i}");UpdatedBoons(r);Check(r.AffixDescriptions.Count==5,"one signature and four boons");Check(r.Backpack.ExtraRows==v.StorageRows&&r.Backpack.ExtraColumns==v.StorageColumns,"roll matches permanent capacity");Check(r.AffixDescriptions.Count(s=>s.StartsWith("Expanded Storage"))==(v.StorageRows>0?1:0),"row boon exactly once");Check(r.AffixDescriptions.Count(s=>s.StartsWith("Widened Storage"))==(v.StorageColumns>0?1:0),"column boon exactly once");Check(r.AffixDescriptions.Skip(1).Select(s=>s.Split(' ')[0]).Distinct().Count()==4,"distinct random boons");if(v.StorageRows>0)Check(r.BuildDescriptionBlock().Contains($"+{v.StorageRows} "),"row count rendered");}});
Run("Identical-layout copies can retain different remaining random boons",()=>{foreach(var v in layouts){var rolls=Enumerable.Range(0,20).Select(i=>Fingerprint(Roll(v.TemplateId,"variation-"+i+v.TemplateId))).ToHashSet();Check(rolls.Count>1,"per-instance variation");}});
Run("Existing bags retain selected boons, unrelated values and permanent storage while weight boons update",()=>{foreach(var b in originals)for(int i=0;i<100;i++){var item=new Item{Id="legacy-"+b.TemplateId+"-"+i,StringTemplateId=b.TemplateId};var a=C.RarityResolver.Resolve(item)!;var old=L.LegacyRarityResolver.Resolve(item)!;Compatible(a.AffixDescriptions,old.AffixDescriptions);UpdatedBoons(a);Check(a.Backpack.ExtraRows==0&&a.Backpack.ExtraColumns==0,"no old capacity change");Near(a.Backpack.SearchTime,old.Backpack.SearchTime,"old search");Near(a.Backpack.SprintCost,old.Backpack.SprintCost,"old sprint");Near(a.Backpack.LegRecovery,old.Backpack.LegRecovery,"old recovery");Near(a.Backpack.AimCost,old.Backpack.AimCost,"old aim");Near(a.Backpack.MovementNoise,old.Backpack.MovementNoise,"old sound");}});
Run("Gun and melee random modifiers remain unchanged",()=>{foreach(var v in client.Variants.Where(v=>v.BackpackEffect==null&&v.ChestRigEffect==null).Take(100))for(int i=0;i<5;i++){var item=new Item{Id="normal-"+v.TemplateId+"-"+i,StringTemplateId=v.TemplateId};var now=C.RarityResolver.Resolve(item)!;var old=L.LegacyRarityResolver.Resolve(item)!;Check(now.AffixDescriptions.SequenceEqual(old.AffixDescriptions),"non-bag roll unchanged");}});
Run("Rolls survive item save/load, cache reset and unrelated resolution order",()=>{var snapshots=layouts.Select(v=>(Item:new Item{Id="persist-"+v.TemplateId,StringTemplateId=v.TemplateId},Definition:v)).ToArray();var before=snapshots.ToDictionary(x=>x.Item.Id,x=>Fingerprint(C.RarityResolver.Resolve(x.Item)!));C.RarityResolver.ResetSession();foreach(var x in snapshots.Reverse()){var stored=JsonSerializer.Serialize(x.Item);var reload=JsonSerializer.Deserialize<Item>(stored)!;Check(Fingerprint(C.RarityResolver.Resolve(reload)!)==before[x.Item.Id],"saved ID/TPL restores exact roll");}});
Run("Template IDs are stable across cultures",()=>{var saved=CultureInfo.CurrentCulture;try{foreach(var culture in new[]{"en-US","fr-FR","ar-SA"}){CultureInfo.CurrentCulture=CultureInfo.GetCultureInfo(culture);foreach(var v in layouts)Check(C.BackpackStorageVariants.CurrentId(v.StorageFamilyId,v.StorageRows,v.StorageColumns)==v.TemplateId,"culture-independent ID");}}finally{CultureInfo.CurrentCulture=saved;}});
Run("Native server grids add rows/columns once, retain external size and other pockets",()=>{foreach(var v in server.Variants.Where(v=>v.BackpackEffect!=null)){var source=Base();var unchanged=JsonSerializer.Serialize(source,opts);var e=v.BackpackEffect!;var result=S.BackpackStorage.Apply(source,e,v.TemplateId,v.StorageRows>0||v.StorageColumns>0);var n=Node(result);var main=n["Grids"]![0]!["_props"]!;Check(main["cellsH"]!.GetValue<int>()==6+e.ExtraColumns,"main width");Check(main["cellsV"]!.GetValue<int>()==7+e.ExtraRows,"main height");Check(n["Width"]!.GetValue<int>()==2&&n["Height"]!.GetValue<int>()==3,"external footprint unchanged");Check(n["Grids"]![1]!["_props"]!["cellsH"]!.GetValue<int>()==2&&n["Grids"]![1]!["_props"]!["cellsV"]!.GetValue<int>()==2,"other pockets unchanged");Check(n["Grids"]!.AsArray().Count==2+e.ExtraGrids.Count,"only signature compartments added");Check(JsonSerializer.Serialize(source,opts)==unchanged,"source properties never mutated");if(v.StorageRows>0||v.StorageColumns>0)Check(n["GridLayoutName"]==null,"dynamic UI layout selected");}});
Run("Existing fixed storage signatures compose with both random dimensions",()=>{foreach(var baseBag in originals.Where(b=>b.BackpackEffect!.ExtraRows>0||b.BackpackEffect!.ExtraGrids.Count>0)){var v=byServer[C.BackpackStorageVariants.CurrentId(baseBag.TemplateId,2,2)];Check(v.BackpackEffect!.ExtraRows==baseBag.BackpackEffect!.ExtraRows+2,"signature rows plus boon");Check(v.BackpackEffect.ExtraGrids.Count==baseBag.BackpackEffect.ExtraGrids.Count,"signature pockets retained");foreach(var pair in v.BackpackEffect.ExtraGrids.Zip(baseBag.BackpackEffect.ExtraGrids))Check(pair.First.Width==pair.Second.Width&&pair.First.Height==pair.Second.Height&&pair.First.FirearmsOnly==pair.Second.FirearmsOnly,"signature filters retained");}});
Run("Edge-cell loot survives a native template and inventory JSON round trip",()=>{foreach(var v in layouts){var d=byServer[v.TemplateId];var n=Node(S.BackpackStorage.Apply(Base(),d.BackpackEffect!,d.TemplateId,d.StorageRows>0||d.StorageColumns>0));var nativeReload=JsonSerializer.Deserialize<TemplateItemProperties>(n.ToJsonString(),opts)!;var grid=Node(nativeReload)["Grids"]![0]!["_props"]!;var x=grid["cellsH"]!.GetValue<int>()-1;var y=grid["cellsV"]!.GetValue<int>()-1;var item=new{_id="bag-instance",_tpl=v.TemplateId,children=new[]{new{parentId="bag-instance",slotId="main",location=new{x,y,r=0}}}};var save=JsonNode.Parse(JsonSerializer.Serialize(item))!;var restored=byServer[save["_tpl"]!.GetValue<string>()];var after=Node(S.BackpackStorage.Apply(Base(),restored.BackpackEffect!,restored.TemplateId,restored.StorageRows>0||restored.StorageColumns>0));Check(save["children"]![0]!["location"]!["x"]!.GetValue<int>()<after["Grids"]![0]!["_props"]!["cellsH"]!.GetValue<int>(),"last column remains valid");Check(save["children"]![0]!["location"]!["y"]!.GetValue<int>()<after["Grids"]![0]!["_props"]!["cellsV"]!.GetValue<int>(),"last row remains valid");}});
var allNew=server.Variants.Where(v=>v.BackpackEffect!=null&&v.StorageRollVersion==S.BackpackStorageVariants.CurrentLayoutVersion&&!v.IsMysteryFleaOffer&&v.SpawnEnabled).ToArray();var weights=allNew.ToDictionary(v=>v.TemplateId,v=>v.SpawnWeight);var sources=allNew.GroupBy(v=>v.SourceTemplateId).ToDictionary(g=>g.Key,g=>g.Select(v=>v.TemplateId).ToArray());
Run("Storage boons have the same 40% marginal as each of ten random bonuses",()=>{foreach(var family in allNew.GroupBy(v=>v.StorageFamilyId)){var sum=family.Sum(v=>v.SpawnWeight);Near(sum,30,"family weight");Near(family.Where(v=>v.StorageRows>0).Sum(v=>v.SpawnWeight)/sum,.4,"row chance");Near(family.Where(v=>v.StorageColumns>0).Sum(v=>v.SpawnWeight)/sum,.4,"column chance");Near(family.Where(v=>v.StorageRows>0&&v.StorageColumns>0).Sum(v=>v.SpawnWeight)/sum,2d/15d,"both chance");Near(family.Where(v=>v.StorageRows==1).Sum(v=>v.SpawnWeight),family.Where(v=>v.StorageRows==2).Sum(v=>v.SpawnWeight),"equal row amount chances");}});
foreach(var fraction in new[]{0d,.0025,.01,.1})Run("Standalone/APBS combined fraction remains "+fraction,()=>{var originalsPool=sources.Keys.Select((k,i)=>(k,w:(double)i+1)).ToDictionary(p=>p.k,p=>p.w);originalsPool["other-mod-bag"]=777;var copy=originalsPool.ToDictionary(p=>p.Key,p=>p.Value);var rolled=S.CategorySpawnPolicy.Weights(originalsPool,sources,fraction,weights);Near(rolled.Values.Sum()/(originalsPool.Values.Sum()+rolled.Values.Sum()),fraction,"combined rate");Check(originalsPool.SequenceEqual(copy),"other weights unchanged");Check(rolled.Keys.All(k=>weights.ContainsKey(k)),"only eligible EFB layouts");if(fraction==0)Check(rolled.Count==0,"zero removes all generated layouts");});
Run("APBS-filtered layouts are not reintroduced and still meet the combined target",()=>{var allowed=sources.ToDictionary(p=>p.Key,p=>p.Value.Where(id=>byServer[id].StorageColumns==0).ToArray());var pool=sources.Keys.ToDictionary(k=>k,k=>1d);var r=S.CategorySpawnPolicy.Weights(pool,allowed,.01,weights);Check(r.Keys.All(id=>byServer[id].StorageColumns==0),"filter decisions preserved");Near(r.Values.Sum()/(pool.Values.Sum()+r.Values.Sum()),.01,"filtered target");});
Run("Boss pools use their natural backpack sources and the same layout weights",()=>{var source=sources.First();var pool=new Hashtable{{source.Key,100d},{"other-mod-bag",50d}};var variants=allNew.GroupBy(v=>v.SourceTemplateId).ToDictionary(g=>g.Key,g=>g.ToArray());Check(S.BossFixture.Apply(pool,variants,.1,out var count),"boss pool populated");Check(count==source.Value.Length,"only natural source variants");var added=source.Value.Sum(k=>Convert.ToDouble(pool[k]));Near(added/(150+added),.1,"boss target");Near(Convert.ToDouble(pool["other-mod-bag"]),50,"other mod unchanged");var family=allNew.Where(v=>v.StorageFamilyId==byServer[source.Value[0]].StorageFamilyId).ToArray();var a=family.First(v=>v.StorageRows==0&&v.StorageColumns==0);var b=family.First(v=>v.StorageRows==2&&v.StorageColumns==2);Near(Convert.ToDouble(pool[a.TemplateId])/Convert.ToDouble(pool[b.TemplateId]),10,"weighted layouts");});
Run("Backpack rollout does not alter gun/melee weighting",()=>{var pool=new Dictionary<string,double>{{"vanilla",100},{"modded",50}};var variants=new Dictionary<string,string[]>{{"vanilla",new[]{"gun1","gun2"}}};var map=new Dictionary<string,double>{{"gun1",1},{"gun2",1}};var a=S.CategorySpawnPolicy.Weights(pool,variants,.01);var b=S.CategorySpawnPolicy.Weights(pool,variants,.01,map);Check(a.SequenceEqual(b),"unit weights identical");});
var mysteryClient=client.Variants.Where(v=>v.BackpackEffect!=null&&v.IsMysteryFleaOffer).ToArray();
var flea=new S.BackpackFleaRolls(server.Variants,true);
Run("Exactly one mystery identity per signature, excluded from all spawn pools",()=>{Check(mysteryClient.Length==67,"one stock identity each");foreach(var b in originals){var m=mysteryClient.Single(v=>v.StorageFamilyId==b.TemplateId);Check(m.TemplateId==C.BackpackStorageVariants.MysteryId(b.TemplateId),"stable stock ID");Check(!m.SpawnEnabled&&m.SpawnWeight==0,"no spawn chance for mystery stock");Check(!mysteryClient.Any(v=>layouts.Any(l=>l.TemplateId==v.TemplateId)),"stock differs from owned IDs");Check(m.SourceTemplateId==b.SourceTemplateId&&m.EffectText==b.EffectText,"same base and signature");Check(byServer[m.TemplateId].IsMysteryFleaOffer,"server agrees stock is mystery");}});
Run("Flea previews show the signature, four question marks and neutral boons",()=>{foreach(var m in mysteryClient)for(var i=0;i<5;i++){var roll=Roll(m.TemplateId,"mystery-preview-"+m.TemplateId+"-"+i);Check(roll.AffixDescriptions.Count==5&&roll.AffixDescriptions[0]==m.EffectText,"visible signature");Check(roll.AffixDescriptions.Skip(1).All(s=>s=="????"),"exactly four unknowns");Check(roll.Backpack.ExtraRows==0&&roll.Backpack.ExtraColumns==0,"no revealed storage boon");Near(roll.Backpack.FrameWeight,1,"neutral preview weight");Near(roll.Backpack.SprintCost,1,"neutral preview sprint");Check(roll.BuildDescriptionBlock().Contains("revealed when purchased"),"purchase explanation");}});
Run("Only mystery stock is generated; vanilla, third-party guns and EFB guns keep normal flea behavior",()=>{foreach(var v in server.Variants){var allowed=flea.AllowGeneratedOffer(v.TemplateId);Check(allowed==((v.BackpackEffect==null&&v.ChestRigEffect==null)||v.IsMysteryFleaOffer),"no concrete bag stock including old aliases");}Check(flea.AllowGeneratedOffer("unrelated-third-party-bag"),"third-party stock unchanged");Check(flea.AllowGeneratedOffer("vanilla-bag"),"vanilla stock unchanged");var disabled=new S.BackpackFleaRolls(server.Variants,false);foreach(var b in server.Variants.Where(v=>v.BackpackEffect!=null))Check(!disabled.AllowGeneratedOffer(b.TemplateId),"flea toggle also blocks mystery");});
Run("Purchase layout draws retain the four-of-ten boon probabilities",()=>{foreach(var m in mysteryClient){var counts=new Dictionary<string,int>();for(int i=0;i<300;i++){var tpl=flea.PurchasedTemplate(m.TemplateId,()=> (i+.5)/300d);Check(layouts.Any(v=>v.TemplateId==tpl&&v.StorageFamilyId==m.StorageFamilyId),"same signature family only");counts[tpl]=counts.GetValueOrDefault(tpl)+1;}foreach(var v in layouts.Where(v=>v.StorageFamilyId==m.StorageFamilyId))Near(counts.GetValueOrDefault(v.TemplateId),v.SpawnWeight*10,"weighted capacity roll");}foreach(var edge in new[]{0d,1d})Check(layouts.Any(v=>v.TemplateId==flea.PurchasedTemplate(mysteryClient[0].TemplateId,()=>edge)),"both random endpoints handled");});
Run("Bulk purchase reveals each cloned bag independently without touching offer stock",()=>{var m=mysteryClient[0];var stock=new SPTarkov.Server.Core.Models.Eft.Common.Tables.Item{Id=new("aaaaaaaaaaaaaaaaaaaaaaaa"),Template=new(m.TemplateId)};var stockTpl=stock.Template;var first=new SPTarkov.Server.Core.Models.Eft.Common.Tables.Item{Id=new("bbbbbbbbbbbbbbbbbbbbbbbb"),Template=stock.Template};var second=new SPTarkov.Server.Core.Models.Eft.Common.Tables.Item{Id=new("cccccccccccccccccccccccc"),Template=stock.Template};var child=new SPTarkov.Server.Core.Models.Eft.Common.Tables.Item{Id=new("dddddddddddddddddddddddd"),Template=new("eeeeeeeeeeeeeeeeeeeeeeee"),ParentId=first.Id,SlotId="main"};int callback=0,draw=0;Action<int> cb=n=>callback+=n;var request=new SPTarkov.Server.Core.Models.Eft.Inventory.AddItemsDirectRequest{ItemsWithModsToAdd=new[]{new List<SPTarkov.Server.Core.Models.Eft.Common.Tables.Item>{first,child},new List<SPTarkov.Server.Core.Models.Eft.Common.Tables.Item>{second}},Callback=cb,FoundInRaid=true,UseSortingTable=false};flea.Reveal(request,()=>draw++==0?0:.999999);Check(draw==2&&first.Template!=second.Template,"two independent layout draws");Check(first.Id.ToString()=="bbbbbbbbbbbbbbbbbbbbbbbb"&&second.Id.ToString()=="cccccccccccccccccccccccc","native root IDs retained");Check(child.ParentId==first.Id&&child.Template.ToString()=="eeeeeeeeeeeeeeeeeeeeeeee","children untouched");Check(stock.Template==stockTpl&&stock.Id.ToString()=="aaaaaaaaaaaaaaaaaaaaaaaa","shared stock untouched");Check(ReferenceEquals(request.Callback,cb)&&callback==0,"native callback retained and not called early");Check(request.FoundInRaid==true&&request.UseSortingTable==false,"native inventory flags retained");var id=first.Template.ToString();flea.Reveal(request,()=>throw new Exception("must not reroll"));Check(first.Template.ToString()==id,"repeat handling idempotent");var owned=Roll(first.Template.ToString(),first.Id.ToString());Check(owned.AffixDescriptions.Count==5&&!owned.AffixDescriptions.Contains("????"),"real boons revealed immediately");});
Run("Owned, legacy, gun and vanilla inventory entries never reroll through the reveal path",()=>{foreach(var v in server.Variants.Where(v=>!v.IsMysteryFleaOffer)){var i=new SPTarkov.Server.Core.Models.Eft.Common.Tables.Item{Id=new("aaaaaaaaaaaaaaaaaaaaaaaa"),Template=new(v.TemplateId)};var request=new SPTarkov.Server.Core.Models.Eft.Inventory.AddItemsDirectRequest{ItemsWithModsToAdd=new[]{new List<SPTarkov.Server.Core.Models.Eft.Common.Tables.Item>{i}}};flea.Reveal(request,()=>throw new Exception("owned item consumed random roll"));Check(i.Template.ToString()==v.TemplateId,"known item unchanged");}flea.Reveal(new(),()=>throw new Exception("empty request consumed roll"));Check(flea.PurchasedTemplate("third-party",()=>throw new Exception())=="third-party","unknown unaffected");});
C.BackpackGridLayout.Frame F(float x,float y,float w,float h)=>new(x,y,w,h);
Run("Paratus-style pockets remain below the main compartment for every storage size",()=>{var original=new[]{F(0,0,379,442),F(0,446,190,127),F(194,446,190,127)};for(int r=0;r<=2;r++)for(int c=0;c<=2;c++){var w=new float[]{379+c*63,190,190};var h=new float[]{442+r*63,127,127};var p=C.BackpackGridLayout.Preserve(original,w,h,4,false);Near(p[1].X,0,"left pocket stays left");Near(p[2].X,194,"right pocket keeps vanilla offset");Near(p[1].Y,h[0]+4,"pockets below expanded main");Near(p[2].Y,h[0]+4,"pockets remain in same row");}});
Run("Side and lower pockets move only along the grown dimension",()=>{var o=new[]{F(20,10,253,316),F(277,10,127,127),F(20,330,127,127),F(277,330,127,127),F(0,10,16,127)};var w=o.Select(x=>x.Width).ToArray();var h=o.Select(x=>x.Height).ToArray();w[0]+=126;h[0]+=63;var p=C.BackpackGridLayout.Preserve(o,w,h,4,false);Near(p[1].X,403,"right pocket shifted outward");Near(p[1].Y,10,"right pocket height unchanged");Near(p[2].X,20,"lower pocket x unchanged");Near(p[2].Y,393,"lower pocket shifted down");Near(p[3].X,403,"diagonal pocket x");Near(p[3].Y,393,"diagonal pocket y");Near(p[4].X,0,"left pocket unchanged");Near(p[0].X,20,"main stays put");var again=C.BackpackGridLayout.Preserve(o,w,h,4,false);for(int i=0;i<p.Length;i++)Check(p[i].X==again[i].X&&p[i].Y==again[i].Y,"reopening never accumulates offsets");});
