Run("Native 4.0.13 targets and argument bindings match production hooks",()=>{var flags=System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance;var generator=typeof(SPTarkov.Server.Core.Generators.Ragfair.RagfairOfferGenerator).GetMethod("CreateOffersFromAssort",flags)!;var inventory=typeof(SPTarkov.Server.Core.Helpers.Profile.InventoryHelper).GetMethod("AddItemsToStash",flags)!;Check(generator.ReturnType==typeof(void)&&generator.GetParameters()[0].Name=="assortItemWithChildren","native offer contract");Check(inventory.ReturnType==typeof(void)&&inventory.GetParameters()[1].Name=="request","native purchase request contract");foreach(var pair in new[]{(Name:"Generate",Target:generator),(Name:"BeforeAdd",Target:inventory)}){var hook=typeof(S.BackpackFleaMarket).GetMethod(pair.Name,System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic)!;foreach(var arg in hook.GetParameters())Check(pair.Target.GetParameters().Any(p=>p.Name==arg.Name&&p.ParameterType==arg.ParameterType),"Harmony argument name/type matches native target");}});

TemplateItemProperties Shape(params (int W,int H)[] dimensions)
{
 var n=Node(Base());var grids=new JsonArray();int ix=0;
 foreach(var (w,h) in dimensions){grids.Add(new JsonObject{["_id"]=(++ix).ToString("x24"),["_name"]="grid"+ix,["_parent"]="222222222222222222222222",["_props"]=new JsonObject{["cellsH"]=w,["cellsV"]=h,["filters"]=new JsonArray()}});}
 n["Grids"]=grids;return JsonSerializer.Deserialize<TemplateItemProperties>(n.ToJsonString(),opts)!;
}
(int W,int H) Size(JsonObject n,int i)=>(n["Grids"]![i]!["_props"]!["cellsH"]!.GetValue<int>(),n["Grids"]![i]!["_props"]!["cellsV"]!.GetValue<int>());
Run("Every old storage identity and instance roll survives corrected target descriptions",()=>{
 var before=originals.Select(v=>v.Copy()).ToList();EscapeFromBorderlands.PreLargest.HistoricalStorageVariants.Expand(before);
 foreach(var old in before.Where(v=>v.StorageRollVersion==1&&!v.IsMysteryFleaOffer)){
  var retained=client.Variants.Single(v=>v.TemplateId==old.TemplateId);Check(!retained.SpawnEnabled,"legacy storage no longer generated");Check(retained.StorageRollVersion==1&&retained.BackpackEffect!.ExtraRows==old.BackpackEffect!.ExtraRows&&retained.BackpackEffect.ExtraColumns==old.BackpackEffect.ExtraColumns,"saved layout roll parameters preserved");
  for(int i=0;i<10;i++){var item=new Item{Id="v1-owned-"+old.TemplateId+"-"+i,StringTemplateId=old.TemplateId};var was=EscapeFromBorderlands.PreLargest.HistoricalStorageResolver.Resolve(item)!;var now=C.RarityResolver.Resolve(item)!;Compatible(now.AffixDescriptions,was.AffixDescriptions);UpdatedBoons(now);Near(now.Backpack.SearchTime,was.Backpack.SearchTime,"legacy search");Near(now.Backpack.SprintCost,was.Backpack.SprintCost,"legacy sprint");Near(now.Backpack.LegRecovery,was.Backpack.LegRecovery,"legacy recovery");Near(now.Backpack.AimCost,was.Backpack.AimCost,"legacy aim");Near(now.Backpack.MovementNoise,was.Backpack.MovementNoise,"legacy noise");Check(now.Backpack.ExtraRows==was.Backpack.ExtraRows&&now.Backpack.ExtraColumns==was.Backpack.ExtraColumns,"legacy storage amount");}
 }
 foreach(var m in before.Where(v=>v.IsMysteryFleaOffer))Check(client.Variants.Any(v=>v.IsMysteryFleaOffer&&v.TemplateId==m.TemplateId),"flea mystery identity remains stable");
 Check(before.Count(v=>v.StorageRollVersion==1&&!v.IsMysteryFleaOffer)==603,"all saved layouts checked");
});
Run("Rush Hour-style storage expands the largest grid even when listed last",()=>{
