  var source=Shape((1,2),(2,2),(2,2),(5,7));var before=JsonSerializer.Serialize(source,opts);var effect=new S.BackpackEffectDefinition{ExtraRows=r,ExtraColumns=c};var n=Node(S.BackpackStorage.Apply(source,effect,"aaaaaaaaaaaaaaaaaaaaaaaa",r+c>0,true));
  Check(Size(n,0)==(1,2)&&Size(n,1)==(2,2)&&Size(n,2)==(2,2),"upper pockets unchanged");Check(Size(n,3)==(5+c,7+r),"rows and columns applied to main grid");Check(JsonSerializer.Serialize(source,opts)==before,"source never mutated");var area=Enumerable.Range(0,4).Sum(i=>Size(n,i).W*Size(n,i).H);Check(area==45+5*r+7*c+r*c,"full rows and columns add their expected capacity");
 }
});
