bagMapField.SetValue(null,bagMap);
SPTarkov.Server.Core.Models.Eft.Match.EndLocalRaidRequestData Raid(SPTarkov.Server.Core.Models.Enums.ExitStatus outcome,string template,string slot="Backpack")=>new(){ServerId="fixture.pmc.raid",Results=new(){Result=outcome,Profile=new(){Inventory=new(){Items=new List<SPTarkov.Server.Core.Models.Eft.Common.Tables.Item>{new(){Id=new("aaaaaaaaaaaaaaaaaaaaaaaa"),Template=new(template),SlotId=slot}}}}}};
void Before(SPTarkov.Server.Core.Models.Eft.Match.EndLocalRaidRequestData request)=>rewardBefore.Invoke(null,new object[]{new SPTarkov.Server.Core.Models.Common.MongoId("bbbbbbbbbbbbbbbbbbbbbbbb"),request});
