Run("Server outcome normalization preserves every non-run-through result",()=>{var pass=server.Variants.First(v=>v.BackpackEffect?.Key=="BP25-2");foreach(var outcome in Enum.GetValues<SPTarkov.Server.Core.Models.Enums.ExitStatus>()){var r=Raid(outcome,pass.TemplateId);Before(r);Check(r.Results!.Result==(outcome==SPTarkov.Server.Core.Models.Enums.ExitStatus.RUNNER?SPTarkov.Server.Core.Models.Enums.ExitStatus.SURVIVED:outcome),"exact outcome boundary "+outcome);}});
Run("Carried Visitor's Pass bags and other backpacks keep normal run-through rules",()=>{var pass=server.Variants.First(v=>v.BackpackEffect?.Key=="BP25-2");foreach(var slot in new[]{"main","hideout","TacticalVest"}){var r=Raid(SPTarkov.Server.Core.Models.Enums.ExitStatus.RUNNER,pass.TemplateId,slot);Before(r);Check(r.Results!.Result==SPTarkov.Server.Core.Models.Enums.ExitStatus.RUNNER,"pass must be worn");}foreach(var bag in server.Variants.Where(v=>v.BackpackEffect!=null&&v.BackpackEffect.Key!="BP25-2")){var r=Raid(SPTarkov.Server.Core.Models.Enums.ExitStatus.RUNNER,bag.TemplateId);Before(r);Check(r.Results!.Result==SPTarkov.Server.Core.Models.Enums.ExitStatus.RUNNER,"other signature does not gain survival");}var vanilla=Raid(SPTarkov.Server.Core.Models.Enums.ExitStatus.RUNNER,pass.SourceTemplateId);Before(vanilla);Check(vanilla.Results!.Result==SPTarkov.Server.Core.Models.Enums.ExitStatus.RUNNER,"vanilla LK 3F unchanged");Before(new(){ServerId="fixture.pmc.raid"});});
