Run("All legacy rolled backpacks correct largest storage additively and preserve old occupied coordinates",()=>{
 foreach(var variant in server.Variants.Where(v=>v.BackpackEffect!=null&&v.StorageRollVersion==1&&!v.IsMysteryFleaOffer)){
  var source=Shape((1,2),(5,7));var old=Node(S.BackpackStorage.Apply(source,variant.BackpackEffect!,variant.TemplateId,variant.StorageRows+variant.StorageColumns>0,false));
  var actual=Node(S.BackpackStorage.Apply(source,variant));
  for(int i=0;i<old["Grids"]!.AsArray().Count;i++){
   Check(Size(actual,i).W>=Size(old,i).W&&Size(actual,i).H>=Size(old,i).H,"every old cell still valid");
   Check(actual["Grids"]![i]!["_name"]!.GetValue<string>()==old["Grids"]![i]!["_name"]!.GetValue<string>(),"saved grid identity retained");
  }
  Check(Size(actual,1)==(5+variant.BackpackEffect!.ExtraColumns,7+variant.BackpackEffect.ExtraRows),"largest gets intended dimensions");
 }
});
